export interface GoogleFontEntry {
  family: string;
  category: FontCategoryName;
  /** Upright weights the css2 API accepts for this family. */
  weights: number[];
}

/** Flat catalogue in category-then-alphabetical order. */
export const GOOGLE_FONTS: GoogleFontEntry[] = FONT_CATEGORY_ORDER.flatMap((category) =>
  RAW[category].map(
    ([family, weights]): GoogleFontEntry => ({
      family,
      category,
      weights: weights.split(",").map((part) => Number.parseInt(part, 10)),
    }),
  ),
);
